<?php
require __DIR__.'/bootstrap.php';admin_required();$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$title=trim($_POST['title']??'');$desc=trim($_POST['description']??'');$type=$_POST['type']==='activity'?'activity':'quiz';$url=trim($_POST['url']??'');
if($title){$s=$pdo->prepare('INSERT INTO exams(title,description,type,activity_url) VALUES(?,?,?,?)');$s->execute([$title,$desc,$type,$type==='activity'?$url:null]);$msg='آیتم اضافه شد.';}else$msg='عنوان الزامی است.';}
$rows=$pdo->query('SELECT id,title,type,active,activity_url FROM exams ORDER BY id DESC')->fetchAll();
header_ui('مدیریت آزمون و تکلیف');if($msg)echo '<p class="ok">'.e($msg).'</p>';
?><div class="card"><h2>افزودن آزمون / فعالیت</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="grid"><label>عنوان<input name="title" required></label><label>نوع<select name="type"><option value="quiz">آزمون سؤالی</option><option value="activity">فعالیت لینک‌دار</option></select></label><label>لینک فعالیت (اختیاری)<input name="url" type="url"></label></div><label>توضیحات<textarea name="description"></textarea></label><button>ثبت</button></form><p>در این نسخه ایجاد آزمون انجام می‌شود؛ ویرایش سؤال‌های چندگزینه‌ای در مرحله اتصال فرانت‌اند افزوده خواهد شد.</p></div><table><tr><th>شناسه</th><th>عنوان</th><th>نوع</th><th>لینک</th></tr><?php foreach($rows as $r):?><tr><td><?=e((string)$r['id'])?></td><td><?=e($r['title'])?></td><td><?=$r['type']==='quiz'?'آزمون':'فعالیت'?></td><td><?php if($r['activity_url'])echo '<a target="_blank" rel="noopener" href="'.e($r['activity_url']).'">مشاهده</a>';?></td></tr><?php endforeach;?></table><?php footer_ui();?>
